using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using FlowLight.Core;
namespace FlowLight.Client;

public partial class MainWindow : Window
{
    sealed record Game(string ID, string Name, string[] Regions, int Version) { public string RuleLabel => Version > 0 ? $"规则版本 {Version} · 选择区服继续" : "规则草稿 · 等待运营发布"; }
    sealed record Line(string ID, string Name, bool Available, double Rtt);
    readonly DispatcherTimer timer = new() { Interval = TimeSpan.FromSeconds(2) };
    readonly System.Windows.Forms.NotifyIcon tray; bool quitting, loggedIn, coreAvailable, polling; string state = "IDLE"; int selectionGeneration;
    public MainWindow() { InitializeComponent(); tray = new() { Icon = System.Drawing.SystemIcons.Application, Text = "流光加速器 · FlowLight Accelerator", Visible = true }; tray.DoubleClick += (_, _) => Dispatcher.Invoke(() => { Show(); WindowState = WindowState.Normal; Activate(); }); var menu = new System.Windows.Forms.ContextMenuStrip(); menu.Items.Add("打开流光加速器", null, (_, _) => Dispatcher.Invoke(() => { Show(); Activate(); })); menu.Items.Add("退出并停止加速", null, (_, _) => Dispatcher.Invoke(async () => await Exit())); tray.ContextMenuStrip = menu; Closing += (_, e) => { if (!quitting) { e.Cancel = true; Hide(); } }; Loaded += async (_, _) => { await Status(); timer.Start(); }; timer.Tick += async (_, _) => await Status(); }
    async Task Status() { if (polling) return; polling = true; try { var result = await Wire.CallAsync("status"); state = result.GetProperty("state").GetString() ?? "IDLE"; loggedIn = result.GetProperty("logged_in").GetBoolean(); if (loggedIn && GameList.ItemsSource == null) await LoadGames(); if (result.TryGetProperty("username", out var username) && username.ValueKind == JsonValueKind.String) AccountLabel.Text = username.GetString(); coreAvailable = result.GetProperty("core_available").GetBoolean(); ServiceLabel.Text = coreAvailable ? "本地服务已连接" : "网络内核待配置"; ConnectionState.Text = state switch { "PREPARING" => "正在准备节点与授权…", "CONNECTING" => "正在连接线路…", "ACTIVE" => "线路已连接 · 请启动所选游戏", "FAILED" => "连接失败", "DEGRADED" => "线路探测异常 · 正在复测", "RECONNECTING" => "正在重新连接…", "STOPPING" => "正在停止并回收资源…", "BUSY" => "本机正在为另一用户加速", _ => "未连接" }; if (result.TryGetProperty("probe", out var p) && p.ValueKind == JsonValueKind.Object) { ProbeTitle.Text = "当前隧道探测"; Latency.Text = p.GetProperty("rtt_ms").GetDouble().ToString("0") + " ms"; ExitAddress.Text = "实际出口 " + p.GetProperty("exit_ip").GetString(); } else ResetEvidence(); var error = result.GetProperty("error").GetString(); if (!string.IsNullOrWhiteSpace(error)) ShowNotice(error); else if (loggedIn && !coreAvailable) ShowNotice("本地服务已连接，网络内核尚未配置。请完成安装配置后开始加速。"); else if (loggedIn) NoticeBox.Visibility = Visibility.Collapsed; UpdateButtons(); } catch { ResetEvidence(false); ServiceLabel.Text = "本地服务未连接"; ShowNotice("本地服务尚未启动。请先安装并配置 FlowLight 本地服务。"); StartButton.IsEnabled = false; StopButton.IsEnabled = false; } finally { polling = false; } }
    void UpdateButtons() { StartButton.IsEnabled = loggedIn && coreAvailable && (state == "IDLE" || state == "FAILED") && GameList.SelectedItem is Game { Version: > 0 } && RegionList.SelectedItem is string && LineList.SelectedItem is Line { Available: true }; StopButton.IsEnabled = state is "PREPARING" or "CONNECTING" or "ACTIVE" or "DEGRADED" or "RECONNECTING"; GameList.IsEnabled = !StopButton.IsEnabled; RegionList.IsEnabled = !StopButton.IsEnabled; LineList.IsEnabled = !StopButton.IsEnabled; }
    void ResetEvidence(bool allowHistory = true) { ProbeTitle.Text = "线路历史探测"; Latency.Text = allowHistory && LineList.SelectedItem is Line { Rtt: > 0 } line ? line.Rtt.ToString("0") + " ms" : "—"; ExitAddress.Text = "尚无当前出口探测"; }
    void ShowNotice(string text) { Notice.Text = text; NoticeBox.Visibility = Visibility.Visible; }
    async Task LoadGames() { var result = await Wire.CallAsync("games"); var list = result.EnumerateArray().Select(g => new Game(g.GetProperty("id").GetString()!, g.GetProperty("name").GetString()!, g.GetProperty("regions").ValueKind == JsonValueKind.Array ? g.GetProperty("regions").EnumerateArray().Select(x => x.GetString()!).ToArray() : [], g.GetProperty("published_version").GetInt32())).ToArray(); GameList.ItemsSource = list; EmptyGames.Text = list.Length == 0 ? "暂无可用游戏，请联系运营人员配置。" : ""; if (list.Length > 0) GameList.SelectedIndex = 0; }
    async void Login_Click(object sender, RoutedEventArgs e) { LoginButton.IsEnabled = false; LoginError.Text = ""; try { var user = await Wire.CallAsync("login", new { username = Username.Text, password = Password.Password }); Password.Clear(); AccountLabel.Text = user.GetProperty("username").GetString(); LoginOverlay.Visibility = Visibility.Collapsed; NoticeBox.Visibility = Visibility.Collapsed; loggedIn = true; await LoadGames(); await Status(); } catch (Exception ex) { LoginError.Text = ex.Message; } finally { LoginButton.IsEnabled = true; } }
    void Account_Click(object sender, RoutedEventArgs e) { LoginOverlay.Visibility = Visibility.Visible; Username.Focus(); }
    void LoginCancel_Click(object sender, RoutedEventArgs e) { Password.Clear(); LoginOverlay.Visibility = Visibility.Collapsed; }
    async void Refresh_Click(object sender, RoutedEventArgs e) { try { await LoadGames(); ShowNotice("已同步服务端游戏与线路配置。"); } catch (Exception ex) { ShowNotice(ex.Message); } }
    void Library_Click(object sender, RoutedEventArgs e) { GameList.Focus(); }
    void Game_Changed(object sender, SelectionChangedEventArgs e) { if (GameList.SelectedItem is not Game game) return; RegionList.ItemsSource = game.Regions; RegionList.SelectedIndex = game.Regions.Length > 0 ? 0 : -1; LineList.ItemsSource = null; ResetEvidence(); LineHint.Text = game.Version == 0 ? "该游戏规则尚未发布" : game.Regions.Length == 0 ? "尚未配置游戏区服" : "选择可用线路"; UpdateButtons(); }
    async void Region_Changed(object sender, SelectionChangedEventArgs e) { var generation = ++selectionGeneration; if (GameList.SelectedItem is not Game game || RegionList.SelectedItem is not string region) { LineList.ItemsSource = null; return; } try { var rows = await Wire.CallAsync("lines", new { game_id = game.ID, region_id = region }); if (generation != selectionGeneration) return; var lines = rows.EnumerateArray().Select(l => new Line(l.GetProperty("id").GetString()!, l.GetProperty("name").GetString()!, l.GetProperty("available").GetBoolean(), l.GetProperty("probe").GetProperty("rtt_ms").GetDouble())).ToArray(); LineList.ItemsSource = lines; LineList.SelectedItem = lines.FirstOrDefault(l => l.Available); LineHint.Text = lines.Length == 0 ? "此区服暂无已验证的授权线路" : "线路按历史探测延迟排列"; UpdateButtons(); } catch (Exception ex) { ShowNotice(ex.Message); } }
    void Line_Changed(object sender, SelectionChangedEventArgs e) { ResetEvidence(); UpdateButtons(); }
    async void Start_Click(object sender, RoutedEventArgs e) { if (GameList.SelectedItem is not Game game || RegionList.SelectedItem is not string region || LineList.SelectedItem is not Line line) return; StartButton.IsEnabled = false; try { await Wire.CallAsync("start", new { game_id = game.ID, region_id = region, line_id = line.ID }); ShowNotice("正在准备连接。通过隧道探测后才会显示线路已连接。"); await Status(); } catch (Exception ex) { ShowNotice(ex.Message); UpdateButtons(); } }
    async void Stop_Click(object sender, RoutedEventArgs e) { StopButton.IsEnabled = false; try { await Wire.CallAsync("stop"); await Status(); } catch (Exception ex) { ShowNotice(ex.Message); } }
    async void Diagnostics_Click(object sender, RoutedEventArgs e) { try { var result = await Wire.CallAsync("status"); System.Windows.Clipboard.SetText(JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true })); ShowNotice("连接诊断已复制，不包含账号密码或隧道密钥。"); } catch (Exception ex) { ShowNotice(ex.Message); } }
    async void Exit_Click(object sender, RoutedEventArgs e) => await Exit();
    async Task Exit() { try { await Wire.CallAsync("stop"); } catch { } quitting = true; timer.Stop(); tray.Dispose(); System.Windows.Application.Current.Shutdown(); }
}
